package com.shale.data.dao;
import static org.junit.jupiter.api.Assertions.*;import java.nio.file.*;import org.junit.jupiter.api.Test;
class UserSessionMigrationContractTest{
	private static final Path M=Path.of("..","docs","sql","2026-09-29_user_sessions_foundation_phase7a.sql"),V=Path.of("..","docs","sql","verification","2026-09-29_user_sessions_phase7a_verification.sql"),R=Path.of("..","docs","sql","verification","2026-09-29_user_sessions_phase7a_rls.sql");
	@Test void additiveSchemaHasTenantOwnershipLifecycleCredentialAndStrictRls()throws Exception{String s=Files.readString(M);for(String x:new String[]{"UserSessions","Id bigint IDENTITY","SessionId uniqueidentifier NOT NULL","CurrentAccessJti uniqueidentifier NOT NULL","ExpiresAt datetime2(7) NOT NULL","RevokedAt datetime2(7) NULL","RowVer rowversion NOT NULL","FK_UserSessions_UserTenant","FK_UserSessions_InstanceTenant","ON DELETE NO ACTION","ClientType IN('DESKTOP','WEB','MOBILE')","fn_FilterByTenant(ShaleClientId)","AFTER INSERT","AFTER UPDATE","SET XACT_ABORT ON","THROW;"})assertTrue(s.contains(x),x);var table=java.util.regex.Pattern.compile("CREATE TABLE\\s+dbo\\.UserSessions\\s*\\((.*?)\\);", java.util.regex.Pattern.CASE_INSENSITIVE | java.util.regex.Pattern.DOTALL).matcher(s);
        assertTrue(table.find(),"UserSessions table declaration is required");
        // The dynamic RLS statement variable may be nvarchar(max); persisted session columns may not.
        for(String forbidden:new String[]{"nvarchar(max)","AccessToken","RefreshToken","Password","MfaSecret"})
            assertFalse(table.group(1).contains(forbidden),forbidden);
        assertFalse(s.contains("fn_FilterByTenantOrGlobal"),"Session RLS must remain strict");}
	@Test void verifiersAreSimpleAndUseAnExplicitNonDboPrincipal()throws Exception{String v=Files.readString(V),r=Files.readString(R);assertTrue(v.contains("FindingCount"));for(String x:new String[]{"UniqueIdentifiers","TrustedForeignKeys","LifecycleConstraints","StrictRlsCount","NoSeedRows","PriorPhaseTablesIntact"})assertTrue(v.contains(x),x);for(String x:new String[]{"CREATE USER","WITHOUT LOGIN","EXECUTE AS USER","CrossTenantInsertBlocked33504","CrossTenantUpdateBlocked33504","DROP USER"})assertTrue(r.contains(x),x);}
	@Test void migrationIsCompatibilityOnlyAndDoesNotWireAuthentication()throws Exception{String s=Files.readString(M);assertTrue(s.contains("No login, refresh, logout, JWT validation"));assertFalse(s.contains("ALTER TABLE dbo.Users"));assertFalse(s.contains("INSERT dbo.UserSessions"));assertTrue(s.contains("ApplicationInstances"));assertTrue(s.contains("AdministrativeReadAuditLog")||Files.readString(V).contains("AdministrativeReadAuditLog"));}
}
